1→# 清泉中心 Ingest 客户端（Stage A 旁路）
# 由 run-multi-store.ps1 dot-source 使用；也可单独点测。
#
# 依赖 config.qingquan:
# {
#   "enabled": true,
#   "baseUrl": "http://127.0.0.1:8000",
#   "apiKey": "dev-ingest-key",
#   "source": "tiktok_ads",
10→#   "failOpen": true,
#   "timeoutSec": 30
# }

function Get-QingquanConfig($cfg) {
  if (-not $cfg.qingquan) {
    return [pscustomobject]@{
      enabled    = $false
      baseUrl    = 'http://127.0.0.1:8000'
      apiKey     = ''
20→      source     = 'tiktok_ads'
      failOpen   = $true
      timeoutSec = 30
    }
  }
  $q = $cfg.qingquan
  $enabled = $false
  if ($null -ne $q.enabled) { $enabled = [bool]$q.enabled }
  $failOpen = $true
  if ($null -ne $q.failOpen) { $failOpen = [bool]$q.failOpen }
30→  $timeout = 30
  if ($null -ne $q.timeoutSec) { $timeout = [int]$q.timeoutSec }
  $source = 'tiktok_ads'
  if ($q.source) { $source = [string]$q.source }
  $base = 'http://127.0.0.1:8000'
  if ($q.baseUrl) { $base = [string]$q.baseUrl }
  $key = ''
  if ($q.apiKey) { $key = [string]$q.apiKey }
  return [pscustomobject]@{
    enabled    = $enabled
40→    baseUrl    = $base.TrimEnd('/')
    apiKey     = $key
    source     = $source
    failOpen   = $failOpen
    timeoutSec = $timeout
  }
}

function Get-FeishuWriteMode($cfg) {
  # direct | dual | center
50→  $mode = 'direct'
  if ($cfg.feishu -and $cfg.feishu.writeMode) {
    $mode = [string]$cfg.feishu.writeMode
  } elseif ($cfg.qingquan -and $cfg.qingquan.enabled) {
    # 启用清泉但未写 writeMode 时，Stage A 默认 dual
    $mode = 'dual'
  }
  $mode = $mode.ToLowerInvariant()
  if ($mode -notin @('direct', 'dual', 'center')) { $mode = 'direct' }
  return $mode
60→}

function ConvertTo-QingquanIngestItems {
  param(
    [Parameter(Mandatory = $true)] $Rows,
    [Parameter(Mandatory = $true)] [string]$CollectedAt
  )
  $items = @()
  foreach ($r in @($Rows)) {
    $campaign = [string]$r.campaign
70→    if (-not $campaign) { continue }
    $storeId = [string]$r.storeId
    $bizDate = [string]$r.date
    $spend = 0; if ($null -ne $r.spend) { $spend = [double]$r.spend }
    $orders = 0; if ($null -ne $r.orders) { $orders = [double]$r.orders }
    $roi = $null; if ($null -ne $r.roi) { $roi = [double]$r.roi }
    $revenue = 0; if ($null -ne $r.revenue) { $revenue = [double]$r.revenue }
    $status = 'success'; if ($r.status) { $status = [string]$r.status }
    $sourceUrl = ''; if ($r.sourceUrl) { $sourceUrl = [string]$r.sourceUrl }
    $storeName = ''; if ($r.store) { $storeName = [string]$r.store }
80→
    $items += [ordered]@{
      platform         = 'tiktok'
      shop_id          = $storeId
      shop_name        = $storeName
      biz_date         = $bizDate
      collected_at     = $CollectedAt
      idempotency_key  = ("tiktok_ads:{0}:{1}:{2}" -f $storeId, $campaign, $bizDate)
      payload          = [ordered]@{
        campaign_name = $campaign
90→        spend         = $spend
        orders        = $orders
        roi           = $roi
        revenue       = $revenue
        row_status    = $status
        currency      = 'GBP'
        source_url    = $sourceUrl
      }
      evidence         = [ordered]@{
        source_url = $sourceUrl
100→      }
    }
  }
  return $items
}

function Send-QingquanIngest {
  param(
    [Parameter(Mandatory = $true)] $Config,
    [Parameter(Mandatory = $true)] $Items,
110→    [switch]$Quiet
  )
  $q = Get-QingquanConfig $Config
  if (-not $q.enabled) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
  }
  if (-not $q.apiKey) {
    $msg = 'qingquan.apiKey empty'
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning $msg }
120→      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = @($Items).Count }
    }
    throw $msg
  }
  if (@($Items).Count -eq 0) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
  }

  $url = "{0}/api/v1/ingest/{1}" -f $q.baseUrl, $q.source
  $payload = @{ items = @($Items) }
130→  $json = $payload | ConvertTo-Json -Depth 10 -Compress
  # PS 5.1 ConvertTo-Json 对中文可能转义；UTF8 字节发送
  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($json)

  try {
    $resp = Invoke-RestMethod -Method Post -Uri $url -TimeoutSec $q.timeoutSec -ContentType 'application/json; charset=utf-8' -Body $bodyBytes -Headers @{
      'X-Api-Key' = $q.apiKey
    }
    $accepted = 0; $duplicated = 0; $failed = 0
    if ($null -ne $resp.accepted) { $accepted = [int]$resp.accepted }
140→    if ($null -ne $resp.duplicated) { $duplicated = [int]$resp.duplicated }
    if ($null -ne $resp.failed) { $failed = [int]$resp.failed }
    return [pscustomobject]@{
      ok         = ($failed -eq 0)
      skipped    = $false
      accepted   = $accepted
      duplicated = $duplicated
      failed     = $failed
      resp       = $resp
      error      = $null
150→    }
  }
  catch {
    $err = [string]$_
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning ("qingquan ingest failed (failOpen): {0}" -f $err) }
      return [pscustomobject]@{
        ok         = $false
        skipped    = $false
        accepted   = 0
160→        duplicated = 0
        failed     = @($Items).Count
        resp       = $null
        error      = $err
      }
    }
    throw
  }
}

170→function Test-QingquanHealth {
  param([Parameter(Mandatory = $true)] $Config)
  $q = Get-QingquanConfig $Config
  $url = "{0}/health" -f $q.baseUrl
  try {
    $r = Invoke-RestMethod -Method Get -Uri $url -TimeoutSec 10
    return [pscustomobject]@{ ok = ($r.status -eq 'ok'); resp = $r; error = $null }
  }
  catch {
    return [pscustomobject]@{ ok = $false; resp = $null; error = [string]$_ }
180→  }
}

1→/* TikTok ads dashboard scraper for ziniao-cli page exec. No // comments (minified to one line). */
(function () {
  function cleanText(t) {
    return String(t ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function parseNumber(value) {
10→    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥USD|GBP|EUR]/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
20→    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  const HEADER_ALIASES = {
    campaign: ['品名', '广告系列', '广告系列名称', '系列名称', 'campaign', 'campaign name', 'product', '名称'],
    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
    orders: ['销量', '订单', 'sku 订单', 'sku订单', 'orders', 'units', 'units sold'],
    roi: ['roi', 'roas', '投资回报率', '投资回报', '回报率'],
    revenue: ['销售额', '总收入', '销售收入', '收入', 'gmv', 'revenue', 'gross revenue']
30→  };

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    const order = ['roi', 'spend', 'orders', 'revenue', 'campaign'];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) continue;
40→        if (field === 'spend' && /平均下单|cost per|per order|\bcpc\b|\bcpa\b/.test(t)) continue;
        return field;
      }
    }
    return null;
  }

  function parseHtmlTable(table) {
    let headerRow = table.querySelector('thead tr') || table.querySelector('tr');
    if (!headerRow) return [];
50→    const headerCells = [...headerRow.querySelectorAll('th, td')];
    const fields = headerCells.map((c) => matchHeaderField(c.innerText || ''));
    if (!fields.some(Boolean)) return [];
    const bodyRows = table.querySelectorAll('tbody tr');
    const rows = bodyRows.length ? [...bodyRows] : [...table.querySelectorAll('tr')].slice(1);
    const results = [];
    for (const tr of rows) {
      const cells = [...tr.querySelectorAll('td, th')];
      if (!cells.length) continue;
      const row = {};
60→      fields.forEach((field, i) => {
        if (!field || !cells[i]) return;
        const text = cleanText(cells[i].innerText || '');
        row[field] = field === 'campaign' ? text : parseNumber(text) ?? text;
      });
      if (row.campaign || row.spend != null || row.revenue != null) results.push(row);
    }
    return results;
  }

70→  function scoreRows(rows) {
    if (!rows || !rows.length) return 0;
    let s = rows.length;
    for (const r of rows.slice(0, 5)) {
      if (r.campaign) s += 2;
      if (r.spend != null && r.spend !== '') s += 2;
      if (r.roi != null) s += 2;
      if (r.revenue != null) s += 2;
    }
    return s;
80→  }

  let best = [];
  let source = 'none';
  for (const table of document.querySelectorAll('table')) {
    const rows = parseHtmlTable(table);
    if (scoreRows(rows) > scoreRows(best)) {
      best = rows;
      source = 'html-table';
    }
90→  }

  best = best.filter(function (r) {
    const c = cleanText(r.campaign || '').toLowerCase();
    if (!c) return false;
    if (['total', '合计', '总计', '汇总', 'summary', 'all'].indexOf(c) >= 0) return false;
    return true;
  });

  let storeHint = '';
100→  var els = document.querySelectorAll('div, span, h1, h2');
  for (var i = 0; i < els.length && i < 300; i++) {
    const t = cleanText(els[i].innerText || '');
    if (t.length > 5 && t.length < 100 && /主要账号|主账号/.test(t)) {
      storeHint = t.replace(/主要账号|主账号/g, '').trim();
      break;
    }
  }

  return JSON.stringify({
110→    ok: best.length > 0,
    source: source,
    storeHint: storeHint,
    url: location.href,
    title: document.title,
    rows: best,
    error: best.length ? null : '未识别到广告表格，请确认已进入广告数据面板'
