1→/**
 * 从拦截到的报表 API JSON 中抽取广告系列字段
 * 结构因接口而异，做多层启发式遍历
 */

import { cleanText, parseNumber } from './normalize.js';

const KEY_MAP = {
  campaign: [
10→    'campaign_name',
    'campaignName',
    'ad_name',
    'adName',
    'name',
    'title',
    'product_name',
    'productName',
    'creative_name'
  ],
20→  spend: [
    'spend',
    'cost',
    'ad_spend',
    'adSpend',
    'stat_cost',
    'statCost',
    'amount_spent',
    'consume'
  ],
30→  orders: [
    'orders',
    'order_count',
    'orderCount',
    'units',
    'units_sold',
    'unitsSold',
    'paid_order_count',
    'conversions',
    'onsite_shopping'
40→  ],
  roi: ['roi', 'roas', 'ROI', 'ROAS', 'complete_payment_roas', 'onsite_roas'],
  revenue: [
    'revenue',
    'gmv',
    'gross_revenue',
    'grossRevenue',
    'total_revenue',
    'onsite_shopping_value',
    'complete_payment',
50→    'sales',
    'income'
  ]
};

/**
 * @param {unknown} payload
 * @returns {object[]}
 */
export function parseApiPayload(payload) {
60→  if (payload == null) return [];
  let data = payload;
  if (typeof payload === 'string') {
    try {
      data = JSON.parse(payload);
    } catch {
      return [];
    }
  }

70→  const list = findArrayOfObjects(data);
  if (!list.length) return [];

  const rows = [];
  for (const item of list) {
    if (!item || typeof item !== 'object') continue;
    const row = extractRow(item);
    if (row.campaign || row.spend != null || row.revenue != null) {
      rows.push(row);
    }
80→  }
  return rows;
}

function extractRow(obj) {
  const flat = flattenObject(obj);
  const row = {};
  for (const [field, keys] of Object.entries(KEY_MAP)) {
    for (const k of keys) {
      if (flat[k] != null && flat[k] !== '') {
90→        row[field] =
          field === 'campaign' ? cleanText(flat[k]) : parseNumber(flat[k]) ?? flat[k];
        break;
      }
    }
    // 大小写不敏感扫一遍
    if (row[field] == null) {
      const lowerKeys = Object.keys(flat);
      for (const k of keys) {
        const hit = lowerKeys.find((x) => x.toLowerCase() === k.toLowerCase());
100→        if (hit && flat[hit] != null && flat[hit] !== '') {
          row[field] =
            field === 'campaign' ? cleanText(flat[hit]) : parseNumber(flat[hit]) ?? flat[hit];
          break;
        }
      }
    }
  }
  return row;
}
110→
/**
 * 扁平化一层 metrics / stats 嵌套
 */
function flattenObject(obj, prefix = '', out = {}, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 4) return out;
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      // 保留浅 key
120→      out[k] = out[k] ?? (typeof v.value !== 'undefined' ? v.value : undefined);
      flattenObject(v, key, out, depth + 1);
      // metrics 常见 { value: 1 }
      if (v.value != null) out[k] = v.value;
    } else if (!Array.isArray(v)) {
      out[k] = v;
      out[key] = v;
    }
  }
  return out;
130→}

/**
 * 在 JSON 树中找「最像报表行」的对象数组
 * @param {unknown} data
 * @returns {object[]}
 */
function findArrayOfObjects(data, depth = 0) {
  if (depth > 8 || data == null) return [];
  if (Array.isArray(data)) {
140→    const objs = data.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
    if (objs.length >= 1 && looksLikeReportRows(objs)) return objs;
    // 继续往子项挖
    for (const item of data.slice(0, 20)) {
      const found = findArrayOfObjects(item, depth + 1);
      if (found.length) return found;
    }
    if (objs.length >= 1) return objs;
    return [];
  }
150→  if (typeof data === 'object') {
    // 优先常见字段
    const prefer = [
      'list',
      'rows',
      'data',
      'items',
      'records',
      'campaigns',
      'result',
160→      'table'
    ];
    for (const k of prefer) {
      if (data[k] != null) {
        const found = findArrayOfObjects(data[k], depth + 1);
        if (found.length) return found;
      }
    }
    for (const v of Object.values(data)) {
      const found = findArrayOfObjects(v, depth + 1);
170→      if (found.length) return found;
    }
  }
  return [];
}

function looksLikeReportRows(objs) {
  const sample = objs.slice(0, 5);
  let hits = 0;
  for (const o of sample) {
180→    const keys = Object.keys(o).join(' ').toLowerCase();
    if (/campaign|spend|cost|roi|roas|gmv|revenue|order|name/.test(keys)) hits += 1;
    // nested metrics
    if (o.metrics || o.stats || o.stat) hits += 1;
  }
  return hits >= 1;
}

/**
 * URL 是否可能是报表接口
190→ * @param {string} url
 */
export function isLikelyReportUrl(url) {
  if (!url) return false;
  const u = url.toLowerCase();
  return /report|stat|metric|campaign|gmv|ads?\/api|shop_ads|analytics|performance|overview|data_list|getlist/.test(
    u
  );
}

1→﻿# Multi-store TikTok ad scrape via ziniao-cli (dynamic store list)
# Usage:
